import { describe, expect, it } from 'vitest';
import {
  asCents,
  MAX_CENTS,
  presentFiadoBalance,
  presentFiadoBalanceWire,
  spellBrl,
  spellSignedBrl,
} from '../src/index';
import { NBSP } from './support/random';

const c = asCents;

describe('spoken money (MoneyInput accessibility)', () => {
  // Expected sentences written by hand from pt-BR cardinal rules, not generated by the helper.
  it.each([
    [0, 'zero reais'],
    [1, 'um centavo'],
    [5, 'cinco centavos'],
    [100, 'um real'],
    [101, 'um real e um centavo'],
    [200, 'dois reais'],
    [1234, 'doze reais e trinta e quatro centavos'],
    [1400, 'catorze reais'],
    [1900, 'dezenove reais'],
    [2100, 'vinte e um reais'],
    [10000, 'cem reais'],
    [10100, 'cento e um reais'],
    [11000, 'cento e dez reais'],
    [94310, 'novecentos e quarenta e três reais e dez centavos'],
    [100000, 'mil reais'],
    [100100, 'mil e um reais'],
    [110000, 'mil e cem reais'],
    [120000, 'mil e duzentos reais'],
    [123400, 'mil duzentos e trinta e quatro reais'],
    [243700, 'dois mil quatrocentos e trinta e sete reais'],
    [1000000, 'dez mil reais'],
    [10000000, 'cem mil reais'],
    [100000000, 'um milhão de reais'],
    [100000050, 'um milhão de reais e cinquenta centavos'],
    [100000100, 'um milhão e um reais'],
    [120000000, 'um milhão e duzentos mil reais'],
    [
      123456789,
      'um milhão duzentos e trinta e quatro mil quinhentos e sessenta e sete reais e oitenta e nove centavos',
    ],
    [200000000, 'dois milhões de reais'],
    [100000000000, 'um bilhão de reais'],
    [100100000000, 'um bilhão e um milhão de reais'],
    [
      99999999999,
      'novecentos e noventa e nove milhões novecentos e noventa e nove mil novecentos e noventa e nove reais e noventa e nove centavos',
    ],
    [
      MAX_CENTS,
      'novecentos e noventa e nove bilhões novecentos e noventa e nove milhões novecentos e noventa e nove mil novecentos e noventa e nove reais e noventa e nove centavos',
    ],
  ])('%i cents → %s', (cents, spoken) => {
    expect(spellBrl(c(cents))).toBe(spoken);
  });

  it('is unsigned; the signed variant says mais/menos and zero has no sign', () => {
    expect(() => spellBrl(c(-1))).toThrow(RangeError);
    expect(spellSignedBrl(c(1200))).toBe('mais doze reais');
    expect(spellSignedBrl(c(-2000))).toBe('menos vinte reais');
    expect(spellSignedBrl(c(0))).toBe('zero reais');
  });

  it('never uses "um mil" and never truncates large values', () => {
    for (let reais = 1000; reais <= 1999; reais += 37) {
      expect(spellBrl(c(reais * 100))).toMatch(/^mil( |$)/);
    }
    expect(spellBrl(c(MAX_CENTS)).length).toBeGreaterThan(100);
  });
});

describe('fiado balance presentation (formatting §3)', () => {
  it('shows debt unsigned with em aberto', () => {
    expect(presentFiadoBalance(c(29000))).toEqual({
      kind: 'debt',
      signedCents: 29000,
      amount: `R$${NBSP}290,00`,
      label: 'em aberto',
      text: `R$${NBSP}290,00 · em aberto`,
    });
  });

  it('shows zero as quitado with no amount', () => {
    expect(presentFiadoBalance(c(0))).toEqual({
      kind: 'settled',
      signedCents: 0,
      amount: null,
      label: 'quitado',
      text: 'quitado',
    });
    expect(presentFiadoBalanceWire(-0).kind).toBe('settled');
  });

  it('shows credit as its absolute value with an explicit + and the mandatory label, keeping the signed value', () => {
    const credit = presentFiadoBalanceWire(-10);
    expect(credit).toEqual({
      kind: 'credit',
      signedCents: -1000,
      amount: `+R$${NBSP}10,00`,
      label: 'crédito do cliente',
      text: `+R$${NBSP}10,00 · crédito do cliente`,
    });
    expect(credit.text.codePointAt(0)).toBe(0x2b); // ASCII plus
    expect(credit.text).not.toContain('−');
  });

  it('maps the extremes of numeric(14,2) and rejects a non-contract value', () => {
    expect(presentFiadoBalance(c(-MAX_CENTS)).amount).toBe(`+R$${NBSP}999.999.999.999,99`);
    expect(() => presentFiadoBalanceWire(0.005)).toThrow(RangeError);
  });
});
